async function ensureDiscordVerificationLayout(guild) {
  if (!guild || !discordVerifiedRoleId || !discordUnverifiedRoleId) {
    console.warn("[Discord] Verification layout skipped: verified or unverified role is not configured.");
    return;
  }

  if (!verificationEnabled) {
    // Verification is turned off — open member channels back up instead of
    // touching the verification channel (which may be deleted). Removes the
    // ViewChannel:false overwrite for Unverified so nobody stays locked out
    // from before it was disabled.
    await guild.channels.fetch();
    const memberChannels = guild.channels.cache.filter(
      (channel) => discordMemberCategoryIds.includes(channel.id)
        || (channel.parentId && discordMemberCategoryIds.includes(channel.parentId)),
    );
    for (const channel of memberChannels.values()) {
      await channel.permissionOverwrites.delete(discordUnverifiedRoleId).catch(() => {});
    }
    const questionsChannel = await guild.channels.fetch(discordQuestionsChannelId).catch(() => null);
    if (questionsChannel?.isTextBased()) {
      await questionsChannel.permissionOverwrites.delete(discordUnverifiedRoleId).catch(() => {});
    }
    console.log("[Discord] Verification is disabled — opened up member channels for Unverified.");
    autoVerifyAllMembers(guild).catch((err) => console.error("[Discord] Auto-verify backfill failed:", err.message));
    return;
  }

  await guild.channels.fetch();
  const memberChannels = guild.channels.cache.filter(
    (channel) => discordMemberCategoryIds.includes(channel.id)
      || (channel.parentId && discordMemberCategoryIds.includes(channel.parentId)),
  );

  for (const channel of memberChannels.values()) {
    try {
      await channel.permissionOverwrites.edit(guild.roles.everyone, {
        ViewChannel: false,
      });
      await channel.permissionOverwrites.edit(discordVerifiedRoleId, {
        ViewChannel: true,
      });
      await channel.permissionOverwrites.edit(discordUnverifiedRoleId, {
        ViewChannel: false,
      });
    } catch (error) {
      console.error(`[Discord] Could not update access for #${channel.name}:`, error.message);
    }
  }

  const questionsChannel = await guild.channels.fetch(discordQuestionsChannelId).catch(() => null);
  if (questionsChannel?.isTextBased()) {
    await questionsChannel.permissionOverwrites.edit(discordVerifiedRoleId, {
      ViewChannel: true,
      SendMessages: true,
      SendMessagesInThreads: true,
      ReadMessageHistory: true,
    });
    await questionsChannel.permissionOverwrites.edit(discordUnverifiedRoleId, {
      ViewChannel: false,
      SendMessages: false,
    });
    for (const staffRoleId of [discordEmployeeRoleId, discordAdminRoleId, discordOwnerRoleId].filter(Boolean)) {
      await questionsChannel.permissionOverwrites.edit(staffRoleId, {
        ViewChannel: true,
        SendMessages: true,
        SendMessagesInThreads: true,
        ReadMessageHistory: true,
        ManageThreads: true,
      });
    }
    if (discordBot.user) {
      await questionsChannel.permissionOverwrites.edit(discordBot.user.id, {
        ViewChannel: true,
        SendMessages: true,
        SendMessagesInThreads: true,
        CreatePrivateThreads: true,
        ManageThreads: true,
        ReadMessageHistory: true,
      });
    }
  } else {
    console.warn("[Discord] Questions channel is missing or is not text based.");
  }

  // Website desk tickets are mirrored into public threads under this staff-only
  // parent. The customer never needs Discord access to this parent; replies are
  // synced back to their website desk inbox.
  const supportChannel = await guild.channels.fetch(discordSupportChannelId).catch(() => null);
  if (supportChannel?.isTextBased()) {
    await supportChannel.permissionOverwrites.edit(guild.roles.everyone, {
      ViewChannel: false,
      SendMessages: false,
    });
    for (const staffRoleId of [discordEmployeeRoleId, discordAdminRoleId, discordOwnerRoleId].filter(Boolean)) {
      await supportChannel.permissionOverwrites.edit(staffRoleId, {
        ViewChannel: true,
        SendMessages: true,
        SendMessagesInThreads: true,
        ReadMessageHistory: true,
        CreatePublicThreads: true,
        ManageThreads: true,
      });
    }
    if (discordBot.user) {
      await supportChannel.permissionOverwrites.edit(discordBot.user.id, {
        ViewChannel: true,
        SendMessages: true,
        SendMessagesInThreads: true,
        CreatePublicThreads: true,
        ManageThreads: true,
        ReadMessageHistory: true,
      });
    }
  } else {
    console.warn("[Discord] Site support channel is missing or is not text based.");
  }

  const verificationChannel = await guild.channels.fetch(discordVerificationChannelId).catch(() => null);
  if (!verificationChannel?.isTextBased()) {
    console.warn("[Discord] Verification channel is missing or is not a text channel.");
    return;
  }

  await verificationChannel.permissionOverwrites.edit(guild.roles.everyone, {
    ViewChannel: false,
    SendMessages: false,
  });
  await verificationChannel.permissionOverwrites.edit(discordUnverifiedRoleId, {
    ViewChannel: true,
    SendMessages: false,
    ReadMessageHistory: true,
  });
  await verificationChannel.permissionOverwrites.edit(discordVerifiedRoleId, {
    ViewChannel: false,
    SendMessages: false,
  });

  const recent = await verificationChannel.messages.fetch({ limit: 50 });
  const existingPanels = recent.filter((message) =>
    message.author.id === discordBot.user.id
    && message.embeds.some((embed) => /verif/i.test(embed.title || "")),
  );
  const primaryPanel = existingPanels.first();
  const panel = primaryPanel
    ? await primaryPanel.edit(buildDiscordVerificationPanel())
    : await verificationChannel.send(buildDiscordVerificationPanel());

  for (const duplicate of existingPanels.values()) {
    if (duplicate.id !== panel.id) {
      await duplicate.delete().catch(() => {});
    }
  }

  if (!panel.pinned) {
    await panel.pin("Keep the XenCheats verification panel easy to find.").catch(() => {});
  }

  console.log(`[Discord] Verification layout ready in #${verificationChannel.name}.`);
}

/* One-time-per-boot backfill: when verification is disabled, give everyone
   the Verified role (and drop Unverified) instead of only opening channel
   permissions — some features check the role directly, not just channel
   access. Runs sequentially with a small delay to stay well under Discord's
   rate limits; safe to re-run since it skips members who already match. */
async function autoVerifyAllMembers(guild) {
  if (!guild || !discordVerifiedRoleId) return;
  const members = await guild.members.fetch();
  let changed = 0;
  for (const member of members.values()) {
    if (member.user?.bot) continue;
    const hasVerified = member.roles.cache.has(discordVerifiedRoleId);
    const hasUnverified = discordUnverifiedRoleId && member.roles.cache.has(discordUnverifiedRoleId);
    if (hasVerified && !hasUnverified) continue;
    if (!hasVerified) await member.roles.add(discordVerifiedRoleId).catch(() => {});
    if (hasUnverified) await member.roles.remove(discordUnverifiedRoleId).catch(() => {});
    changed++;
    await new Promise((resolve) => setTimeout(resolve, 250));
  }
  if (changed) console.log(`[Discord] Auto-verified ${changed} member(s).`);
}

/* Per-user cooldown for public slash commands (they hit Supabase admin APIs).
   Returns true when the user is still cooling down. */
function isOnSlashCooldown(commandName, userId, windowMs = 10_000) {
  const key = `${commandName}:${userId}`;
  const now = Date.now();
  const last = slashCooldownByUser.get(key) || 0;
  if (now - last < windowMs) return true;
  slashCooldownByUser.set(key, now);
  return false;
}

