function getWholesaleCostCents(inventorySlug) {
  return WHOLESALE_COSTS[inventorySlug] || 0;
}

function getStripeFees(amountCents) {
  return Math.round(amountCents * 0.029) + 30;
}

function getStripeCustomerFeeCents(amountCents) {
  const base = Math.max(0, Number(amountCents) || 0);
  return base > 0 ? Math.max(0, Math.ceil((base * 0.029 + 30) / 0.971)) : 0;
}

function isManualDeliverySelection(selection) {
  return Boolean(selection?.product?.manualDelivery || selection?.variant?.manualDelivery);
}

function getSelectionQuantityLimit(selection) {
  const limit = Number(selection?.variant?.quantityLimit || selection?.product?.quantityLimit || 10);
  return Number.isInteger(limit) && limit > 0 ? limit : 10;
}

function getRequestedQuantity(raw, selection) {
  const quantity = Number.parseInt(raw, 10);
  const limit = getSelectionQuantityLimit(selection);
  if (!Number.isInteger(quantity) || quantity < 1) return 1;
  return Math.min(quantity, limit);
}

/* Financial reporting rule: wholesale is 30% below the recorded sale price.
   Keep this separate from WHOLESALE_COSTS, which is used for reseller pricing
   and contains historical/provider-specific values. */
function getReportWholesaleCostCents(saleCents) {
  return Math.max(0, Math.round((Number(saleCents) || 0) * 0.70));
}

function isStripeOrder(order) {
  return typeof order?.stripe_session_id === "string" && order.stripe_session_id.startsWith("cs_");
}

function getReportStripeFeeCents(order, saleCents) {
  return isStripeOrder(order) ? getStripeFees(saleCents) : 0;
}

/* Normalize the two checkout shapes used by the store:
   - single-item Stripe orders store the customer total;
   - cart rows store item subtotals and share one Stripe session.
   This keeps product revenue, wholesale cost, and Stripe fees accurate. */
function buildFinancialOrderRows(orders) {
  const groups = new Map();
  for (const order of orders || []) {
    /* Wallet redemptions are fulfillment records, not new revenue. They are
       stamped with a synthetic balance_* session during delivery, so exclude
       them before grouping to avoid double-counting a prior top-up. */
    if (!isStripeOrder(order)) continue;
    const sessionId = isStripeOrder(order) ? order.stripe_session_id : null;
    const key = sessionId || `order:${order.id || Math.random()}`;
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(order);
  }

  const rows = [];
  for (const group of groups.values()) {
    const rawTotal = group.reduce((sum, order) => sum + Math.max(0, Number(order._reportRawCents) || 0), 0);
    const isCart = group.length > 1 && isStripeOrder(group[0]);
    const sessionFee = isStripeOrder(group[0])
      ? (isCart ? getStripeCustomerFeeCents(rawTotal) : getStripeFees(rawTotal))
      : 0;
    let allocatedFee = 0;

    group.forEach((order, index) => {
      const raw = Math.max(0, Number(order._reportRawCents) || 0);
      const fee = index === group.length - 1
        ? sessionFee - allocatedFee
        : (rawTotal > 0 ? Math.round(sessionFee * raw / rawTotal) : 0);
      allocatedFee += fee;
      rows.push({
        order,
        saleCents: isCart ? raw : Math.max(0, raw - fee),
        stripeFeeCents: fee,
      });
    });
  }
  return rows;
}

/* ── Shared X/Twitter OAuth 1.0a helper ── */
const xPctEnc = (s) => encodeURIComponent(s).replace(/[!'()*]/g, c => `%${c.charCodeAt(0).toString(16).toUpperCase()}`);
function xOauthSign(method, url, params = {}) {
  const oauthParams = {
    oauth_consumer_key: xApiKey,
    oauth_nonce: crypto.randomBytes(16).toString("hex"),
    oauth_signature_method: "HMAC-SHA1",
    oauth_timestamp: String(Math.floor(Date.now() / 1000)),
    oauth_token: xAccessToken,
    oauth_version: "1.0",
  };
  const allParams = { ...oauthParams, ...params };
  const paramStr = Object.keys(allParams).sort().map(k => `${xPctEnc(k)}=${xPctEnc(allParams[k])}`).join("&");
  const baseStr = `${method}&${xPctEnc(url)}&${xPctEnc(paramStr)}`;
  const sigKey = `${xPctEnc(xApiSecret)}&${xPctEnc(xAccessSecret)}`;
  oauthParams.oauth_signature = crypto.createHmac("sha1", sigKey).update(baseStr).digest("base64");
  return "OAuth " + Object.keys(oauthParams).sort().map(k => `${xPctEnc(k)}="${xPctEnc(oauthParams[k])}"`).join(", ");
}
async function xFetch(url, method, params = {}, isJson = false) {
  let headers, res;
  if (isJson) {
    headers = { Authorization: xOauthSign(method, url), "Content-Type": "application/json" };
    res = await fetch(url, { method, headers, body: JSON.stringify(params) });
  } else if (method === "GET") {
    const u = new URL(url);
    const qp = Object.fromEntries(u.searchParams.entries());
    headers = { Authorization: xOauthSign(method, u.origin + u.pathname, qp) };
    res = await fetch(url, { method, headers });
  } else {
    headers = { Authorization: xOauthSign(method, url, params), "Content-Type": "application/x-www-form-urlencoded" };
    res = await fetch(url, { method, headers, body: new URLSearchParams(params).toString() });
  }
  const text = await res.text();
  if (!res.ok) throw new Error(`X API ${res.status}: ${text.slice(0, 200)}`);
  return text ? JSON.parse(text) : {};
}

// Helper: poll Buffer post for externalLink (may not be ready immediately after createPost)
async function pollBufferExternalLink(apiKey, postId, platformName, retries = 3, delayMs = 4000) {
  let bufOrgId = process.env.BUFFER_ORGANIZATION_ID || "";
  if (!bufOrgId) {
    try {
      const oRes = await fetch("https://api.buffer.com", {
        method: "POST",
        headers: { "Content-Type": "application/json", "Authorization": `Bearer ${apiKey}` },
        body: JSON.stringify({ query: `query { account { organizations { id } } }` }),
      });
      const oData = await oRes.json();
      bufOrgId = oData?.data?.account?.organizations?.[0]?.id || "";
    } catch {}
  }
  for (let i = 0; i < retries; i++) {
    await new Promise(r => setTimeout(r, delayMs));
    try {
      const pRes = await fetch("https://api.buffer.com", {
        method: "POST",
        headers: { "Content-Type": "application/json", "Authorization": `Bearer ${apiKey}` },
        body: JSON.stringify({
          query: `query { post(input: { postId: "${postId}", organizationId: "${bufOrgId}" }) { externalLink status } }`,
        }),
      });
      const pData = await pRes.json();
      const link = pData?.data?.post?.externalLink;
      if (link) return `**${platformName}:** ${link}`;
    } catch {}
  }
  return `**${platformName}:** Posted (processing)`;
}

