/* ── Rotate a reseller's API key. Old key stops working the instant this
   runs — anything integrated against it needs updating right away. Returns
   the new raw key once; only the hash + last4 are ever stored. ── */
app.post("/api/reseller/rotate-key", async (req, res) => {
  try {
    const member = await getAuthenticatedUser(req, res);
    if (!supabaseAdmin) {
      return res.status(500).json({ error: "Reseller accounts aren't available right now." });
    }

    if (isOnSlashCooldown(`reseller-rotate-key:${member.id}`, member.id, 60_000)) {
      return res.status(429).json({ error: "Give it a minute before rotating your key again." });
    }

    const { data: reseller, error: fetchError } = await supabaseAdmin
      .from("resellers")
      .select("id, status")
      .eq("user_id", member.id)
      .eq("status", "approved")
      .maybeSingle();
    if (fetchError) throw fetchError;
    if (!reseller) {
      return res.status(404).json({ error: "You don't have an approved reseller account." });
    }

    const rawApiKey = `xr_${createSecretToken(24)}`;
    const { error: updateError } = await supabaseAdmin
      .from("resellers")
      .update({
        api_key_hash: hashToken(rawApiKey),
        api_key_last4: rawApiKey.slice(-4),
        updated_at: new Date().toISOString(),
      })
      .eq("id", reseller.id);
    if (updateError) throw updateError;

    return res.json({ success: true, api_key: rawApiKey, api_key_last4: rawApiKey.slice(-4) });
  } catch (error) {
    console.error("[Reseller rotate key]", error.message);
    return res.status(error.status || 500).json({
      error: error instanceof Error ? error.message : "Unable to rotate your API key.",
    });
  }
});

/* ── Website reseller application form (alternative to Discord /resellerapp) ── */
app.post("/api/reseller/apply", async (req, res) => {
  try {
    const member = await getAuthenticatedUser(req, res);

    if (!supabaseAdmin) {
      return res.status(500).json({ error: "Reseller applications aren't available right now." });
    }

    const discordId = discordIdOf(member);
    if (!discordId) {
      return res.status(400).json({
        error: "Link your Discord account first — approval and your API key are delivered over Discord DM. Link it from your account page, then apply again.",
      });
    }

    const website = trimField(req.body?.website, 200);
    const discordServer = trimField(req.body?.discordServer, 200);
    const volume = trimField(req.body?.volume, 100);
    const why = trimField(req.body?.why, 700);
    const extra = trimField(req.body?.extra, 500);

    if (!website || !discordServer || !volume || !why) {
      return res.status(400).json({ error: "Fill in your website, Discord server, expected volume, and why you want to resell." });
    }

    const { data: existing } = await supabaseAdmin
      .from("resellers")
      .select("id, status")
      .eq("user_id", member.id)
      .in("status", ["pending", "approved"])
      .maybeSingle();

    if (existing?.status === "approved") {
      return res.status(409).json({ error: "You're already an approved reseller — check the Products tab, or ask staff if something looks wrong." });
    }
    if (existing?.status === "pending") {
      return res.status(409).json({ error: "You already have a reseller application pending review." });
    }

    let discordTag = null;
    try {
      if (discordBot && discordGuildId) {
        const guild = await discordBot.guilds.fetch(discordGuildId);
        const guildMember = await guild.members.fetch(discordId).catch(() => null);
        discordTag = guildMember?.user?.tag || null;
      }
    } catch {
      // Non-fatal — the application still gets posted, just without a resolved tag.
    }

    await submitResellerApplication({
      discordId,
      discordTag,
      userId: member.id,
      website,
      discordServer,
      volume,
      why,
      extra,
    });

    return res.json({ success: true });
  } catch (error) {
    console.error("[Reseller apply]", error.message);
    return res.status(error.status || 500).json({
      error: error instanceof Error ? error.message : "Unable to submit your application.",
    });
  }
});

app.get("/api/account", async (req, res) => {
  try {
    const member = await getAuthenticatedUser(req, res);

    const orderSeedResult = await supabaseAdmin
      .from("orders")
      .select(
        "id, product_slug, status, created_at, fulfilled_at, stripe_session_id, stripe_payment_intent"
      )
      .eq("user_id", member.id)
      .order("created_at", { ascending: false });

    if (orderSeedResult.error) {
      throw orderSeedResult.error;
    }

    const paidOrders = (orderSeedResult.data || []).filter((order) => order.status === "paid");

    await Promise.all(
      paidOrders.map((order) =>
        syncPaidOrder({
          id: order.stripe_session_id || null,
          payment_intent: order.stripe_payment_intent || null,
          metadata: {
            orderId: order.id,
          },
        }).catch((error) => {
          console.error("Unable to retry fulfillment for order", order.id, error);
        })
      )
    );

    const [ordersResult, keysResult] = await Promise.all([
      supabaseAdmin
        .from("orders")
        .select("id, product_slug, status, created_at, fulfilled_at, delivered_key_value")
        .eq("user_id", member.id)
        .order("created_at", { ascending: false }),
      supabaseAdmin
        .from("license_keys")
        .select("id, product_slug, key_value, status, assigned_at, assigned_order_id")
        .eq("assigned_user_id", member.id)
        .order("assigned_at", { ascending: false }),
    ]);

    if (ordersResult.error) {
      throw ordersResult.error;
    }

    if (keysResult.error) {
      throw keysResult.error;
    }

    // Build a quick order lookup for linking keys to orders
    const orderMap = new Map();
    for (const o of ordersResult.data || []) {
      orderMap.set(o.id, o);
    }

    // Build license keys from both license_keys table AND order-level delivered keys
    const keysFromTable = (keysResult.data || []).map((licenseKey) => {
      const catalogItem = getCatalogItemByInventorySlug(licenseKey.product_slug);
      const linkedOrder = licenseKey.assigned_order_id
        ? orderMap.get(licenseKey.assigned_order_id)
        : null;
      return {
        id: licenseKey.id,
        productSlug: licenseKey.product_slug,
        baseProductSlug: catalogItem?.product?.slug || licenseKey.product_slug,
        productName: catalogItem?.name || licenseKey.product_slug,
        instructionHref: catalogItem?.product?.instructionHref || "/instructions/",
        keyValue: licenseKey.key_value,
        assignedAt: licenseKey.assigned_at,
        status: licenseKey.status,
        orderId: licenseKey.assigned_order_id || null,
        orderStatus: linkedOrder?.status || null,
        fulfilledAt: linkedOrder?.fulfilled_at || null,
      };
    });

    // Add keys from fulfilled orders that have delivered_key_value (covers sandbox mode)
    const orderDeliveredKeys = (ordersResult.data || [])
      .filter((o) => o.delivered_key_value && o.status === "fulfilled")
      .map((o) => {
        const catalogItem = getCatalogItemByInventorySlug(o.product_slug);
        return {
          id: o.id,
          productSlug: o.product_slug,
          baseProductSlug: catalogItem?.product?.slug || o.product_slug,
          productName: catalogItem?.name || o.product_slug,
          instructionHref: catalogItem?.product?.instructionHref || "/instructions/",
          keyValue: o.delivered_key_value,
          assignedAt: o.fulfilled_at,
          status: "assigned",
          orderId: o.id,
          orderStatus: o.status,
          fulfilledAt: o.fulfilled_at,
        };
      });

    // Merge: use table keys if available, otherwise use order-delivered keys
    const allKeyValues = new Set(keysFromTable.map((k) => k.keyValue));
    const mergedKeys = [
      ...keysFromTable,
      ...orderDeliveredKeys.filter((k) => !allKeyValues.has(k.keyValue)),
    ];

    res.json({
      user: {
        id: member.id,
        email: member.email,
      },
      orders: (ordersResult.data || []).map(normalizeOrder),
      licenseKeys: mergedKeys,
    });
  } catch (error) {
    res.status(error.status || 500).json({
      error: "Unable to load account.",
    });
  }
});

/* Shared catalog builder — used by both the API-key endpoint (GET
   /api/reseller/products) and the session-authed website endpoint (GET
   /api/reseller/catalog) so pricing logic only lives in one place. */
function buildResellerCatalog(reseller) {
  const discountPercent = reseller?.discount_percent || 0;
  const catalog = products
    .filter((product) => isCatalogProductAvailable(product))
    .map((product) => ({
      product_slug: product.slug,
      name: product.name,
      category: product.category || product.game || "Other",
      variants: (product.variants || [])
        .filter((variant) => variant.stockLabel !== "Unavailable" && !variant.checkoutBlocked)
        .map((variant) => {
          const inventorySlug = variant.inventorySlug || `${product.slug}-${variant.slug}`;
          const listAmountCents = variant.amount || 0;
          const yourAmountCents = discountPercent
            ? Math.max(
                Math.round(listAmountCents * (1 - discountPercent / 100)),
                getWholesaleCostCents(inventorySlug) + getStripeFees(listAmountCents) + RESELLER_MIN_MARGIN_CENTS,
              )
            : listAmountCents;
          return {
            variant_slug: variant.slug,
            inventory_slug: inventorySlug,
            name: variant.name,
            list_amount_cents: listAmountCents,
            your_amount_cents: Math.min(yourAmountCents, listAmountCents),
            in_stock: isKeyAvailable(inventorySlug),
          };
        }),
    }))
    .filter((product) => product.variants.length)
    .sort((a, b) => a.category.localeCompare(b.category) || a.name.localeCompare(b.name));

  const lifetimeTopupCents = reseller?.lifetime_topup_cents || 0;
  const currentTier = resellerTierForTopup(lifetimeTopupCents);
  const tierIndex = RESELLER_TOPUP_TIERS.findIndex((t) => t.tier === currentTier.tier);
  const nextTier = tierIndex > 0 ? RESELLER_TOPUP_TIERS[tierIndex - 1] : null; // tiers are listed highest-first

  return {
    tier: reseller?.tier || "legacy",
    discount_percent: discountPercent,
    balance_cents: reseller?.balance_cents ?? null,
    lifetime_purchased_cents: reseller?.lifetime_purchased_cents ?? null,
    lifetime_topup_cents: lifetimeTopupCents,
    current_tier_min_volume_cents: currentTier.minTopupCents,
    next_tier: nextTier
      ? {
          tier: nextTier.tier,
          discount_percent: nextTier.discountPercent,
          cents_to_next_tier: Math.max(0, nextTier.minTopupCents - lifetimeTopupCents),
          min_volume_cents: nextTier.minTopupCents,
        }
      : null,
    products: catalog,
  };
}

/* Read-only catalog listing for reseller API clients — lets them browse
   available products/variants and see their own discounted pricing without
   needing to already know exact inventory slugs. */
app.get("/api/reseller/products", async (req, res) => {
  let reseller = null;
  try {
    ({ reseller } = await ensureResellerApiAccess(req));
  } catch (error) {
    return res.status(error.status || 401).json({
      success: false,
      error: error instanceof Error ? error.message : "API access denied.",
    });
  }

  return res.json({ success: true, ...buildResellerCatalog(reseller) });
});

/* Shared purchase logic — used by both the API-key endpoint (POST
   /api/reseller/buy) and the session-authed website endpoint (POST
   /api/reseller/purchase). `reseller` is null for a legacy flat API key
   (full price, no balance/ledger); non-null for an identified reseller
   (discount applied, debited from their prepaid balance). Returns a plain
   result object — the caller decides the HTTP status/shape. */
async function performResellerPurchase(reseller, selection, quantity) {
  const listAmountCents = (selection.variant.amount || 0) * quantity;
  let chargeAmountCents = listAmountCents;
  if (reseller) {
    const wholesaleCents = getWholesaleCostCents(selection.inventorySlug) * quantity;
    // Nullish (not ||) — a reseller's genuine 0% "New" tier must not be
    // silently overridden by the legacy 25% default.
    const discountPercent = reseller.discount_percent ?? 25;
    const discounted = Math.round(listAmountCents * (1 - discountPercent / 100));
    const floor = wholesaleCents + getStripeFees(listAmountCents) + RESELLER_MIN_MARGIN_CENTS;
    chargeAmountCents = Math.max(discounted, Math.min(floor, listAmountCents));
    if ((reseller.balance_cents || 0) < chargeAmountCents) {
      return {
        success: false,
        error: "Insufficient reseller balance.",
        balance_cents: reseller.balance_cents || 0,
        required_cents: chargeAmountCents,
      };
    }
  }

  const { data: availableKeys, error: availableKeyError } = await supabaseAdmin
    .from("license_keys")
    .select("id, key_value")
    .eq("product_slug", selection.inventorySlug)
    .eq("status", "unused")
    .order("created_at", { ascending: true })
    .limit(quantity);

  if (availableKeyError) {
    throw availableKeyError;
  }

  if ((availableKeys || []).length < quantity) {
    return {
      success: false,
      error: "Out of stock.",
      product_slug: selection.inventorySlug,
      available: (availableKeys || []).length,
    };
  }

  const assignedAt = new Date().toISOString();
  const keyIds = availableKeys.map((key) => key.id);
  const { data: assignedKeys, error: assignError } = await supabaseAdmin
    .from("license_keys")
    .update({
      status: "assigned",
      assigned_at: assignedAt,
    })
    .in("id", keyIds)
    .eq("status", "unused")
    .select("id, key_value");

  if (assignError) {
    throw assignError;
  }

  if ((assignedKeys || []).length < quantity) {
    return { success: false, error: "Stock changed while processing. Try again." };
  }

  const orderNumber = createApiOrderNumber();

  if (reseller) {
    // Debit balance and track lifetime purchase volume for reporting — all
    // best-effort; the keys are already assigned, so a failure here shouldn't
    // lose the sale, just log it for manual review. Tier/discount are driven
    // by lifetime top-up amount (see creditResellerTopupFromStripe), not
    // purchase volume, so they're intentionally left untouched here.
    try {
      const newBalance = (reseller.balance_cents || 0) - chargeAmountCents;
      const newLifetime = (reseller.lifetime_purchased_cents || 0) + chargeAmountCents;
      await supabaseAdmin
        .from("resellers")
        .update({
          balance_cents: newBalance,
          lifetime_purchased_cents: newLifetime,
          updated_at: new Date().toISOString(),
        })
        .eq("id", reseller.id);
      await supabaseAdmin.from("reseller_orders").insert({
        reseller_id: reseller.id,
        inventory_slug: selection.inventorySlug,
        quantity,
        list_amount_cents: listAmountCents,
        discounted_amount_cents: chargeAmountCents,
        order_number: orderNumber,
        license_keys: assignedKeys.map((key) => key.key_value),
      });
    } catch (ledgerError) {
      console.error("[Reseller] Balance/order ledger update failed:", ledgerError.message);
    }
  }

  return {
    success: true,
    order_number: orderNumber,
    product_slug: selection.inventorySlug,
    product_name: selection.name,
    quantity,
    license_key: assignedKeys[0]?.key_value || null,
    license_keys: assignedKeys.map((key) => key.key_value),
    amount_cents: chargeAmountCents,
    balance_cents: reseller ? (reseller.balance_cents || 0) - chargeAmountCents : null,
    fulfilled_at: assignedAt,
  };
}

app.post("/api/reseller/buy", async (req, res) => {
  if (!supabaseAdmin) {
    return res.status(500).json({
      success: false,
      error: "Supabase server auth is not configured.",
    });
  }

  let reseller = null;
  try {
    ({ reseller } = await ensureResellerApiAccess(req));
  } catch (error) {
    return res.status(error.status || 401).json({
      success: false,
      error: error instanceof Error ? error.message : "API access denied.",
    });
  }

  const selection = getResellerProductSelection(req.body);
  const quantity = normalizeApiQuantity(req.body?.quantity);

  if (!selection) {
    return res.status(404).json({ success: false, error: "Product variant not found." });
  }

  if (!isCatalogProductAvailable(selection.product)) {
    return res.status(409).json({ success: false, error: "This product is currently unavailable." });
  }

  try {
    const result = await performResellerPurchase(reseller, selection, quantity);
    return res.json(result);
  } catch (error) {
    return res.status(500).json({ success: false, error: "Unable to complete reseller API order." });
  }
});

/* ── Look up the signed-in site member's approved reseller row, or throw. ── */
async function getApprovedResellerForMember(member) {
  if (!supabaseAdmin) {
    throw Object.assign(new Error("Reseller program is not configured."), { status: 500 });
  }
  const { data: reseller, error } = await supabaseAdmin
    .from("resellers")
    .select("id, discord_id, status, tier, discount_percent, balance_cents, lifetime_purchased_cents")
    .eq("user_id", member.id)
    .eq("status", "approved")
    .maybeSingle();
  if (error || !reseller) {
    throw Object.assign(new Error("You are not an approved reseller."), { status: 403 });
  }
  return reseller;
}

