app.get("/api/admin/order-lookup", async (req, res) => {
  try {
    await ensureRoleAccess(req, res, "staff");
    const query = trimField(req.query.q, 160).toLowerCase();
    if (query.length < 3) return res.status(400).json({ error: "Enter at least 3 characters." });
    let userId = null;
    if (query.includes("@")) {
      const { data, error } = await supabaseAdmin.auth.admin.listUsers({ page: 1, perPage: 1000 });
      if (error) throw error;
      userId = (data.users || []).find((user) => String(user.email || "").toLowerCase() === query)?.id || null;
      if (!userId) return res.json({ orders: [] });
    }
    let lookup = supabaseAdmin
      .from("orders")
      .select("id, product_slug, user_id, status, created_at, fulfilled_at, delivered_key_value")
      .order("created_at", { ascending: false })
      .limit(25);
    // Order IDs are UUIDs, so require the exact value instead of coercing a UUID
    // into a text search at the database layer.
    lookup = userId ? lookup.eq("user_id", userId) : lookup.eq("id", query);
    const { data, error } = await lookup;
    if (error) throw error;
    const orders = (data || []).map((order) => ({
      id: order.id,
      productName: getCatalogItemByInventorySlug(order.product_slug)?.name || order.product_slug,
      status: order.status,
      createdAt: order.created_at,
      fulfilledAt: order.fulfilled_at,
      hasKey: Boolean(order.delivered_key_value),
      key: order.delivered_key_value || null,
    }));
    return res.json({ orders });
  } catch (error) {
    return res.status(error.status || 500).json({ error: "Unable to look up orders." });
  }
});

/* Search the existing immutable admin audit trail. The optional query is only
   used as a filter, so AI/search wording cannot alter or fabricate activity. */
app.get("/api/admin/activity", async (req, res) => {
  try {
    await ensureRoleAccess(req, res, "admin");
    const query = trimField(req.query.q, 120).toLowerCase();
    const { data, error } = await supabaseAdmin
      .from("admin_audit_logs")
      .select("id, action, target_type, target_id, actor_discord_username, details, created_at")
      .order("created_at", { ascending: false })
      .limit(300);
    if (error) throw error;
    const activity = (data || []).filter((row) => {
      if (!query) return true;
      return JSON.stringify(row).toLowerCase().includes(query);
    }).slice(0, 100).map(normalizeAuditLog);
    return res.json({ activity });
  } catch (error) {
    return res.status(error.status || 500).json({ error: "Unable to load staff activity." });
  }
});

/* Transcript files are deliberately served as one shell. The transcript API
   requires an authenticated admin session before it returns any ticket data. */
app.get(/^\/admin\/transcripts\/[a-z0-9-]+\/?$/i, (_req, res) => {
  res.set("Cache-Control", "no-cache");
  res.sendFile(path.join(distDir, "admin/transcripts/index.html"));
});

/* ── Memory cleanup: prune Maps/Sets that grow unbounded ── */
setInterval(() => {
  const now = Date.now();

  // Ticket order-ID/email pending state: normally deleted immediately on
  // completion (success or failure), but a channel where the customer gave
  // an Order ID and then never followed up with an email — e.g. the ticket
  // was closed/archived first — would otherwise leak one small entry
  // forever. Sweep anything past its own expiresAt.
  for (const [key, val] of pendingOrderIdEmailByChannel) {
    if (val?.expiresAt && now > val.expiresAt) pendingOrderIdEmailByChannel.delete(key);
  }

  // Rate-limit maps: entries are { ts } or timestamps - clear entries older than 5 min
  for (const map of [authRateLimitByIp, adminAccessRateLimitByKey, deleteKeyRateLimitByKey, resellerApiRateLimitByKey, orderIdRateLimitByUser, ticketOrderIdRateLimitByChannel]) {
    for (const [key, val] of map) {
      const ts = typeof val === "number" ? val : val?.ts;
      if (ts && now - ts > 5 * 60 * 1000) map.delete(key);
    }
  }

  // signupIpMap: cap at 5000 entries, clear oldest
  if (signupIpMap.size > 5000) signupIpMap.clear();

  // Discord cooldown maps: prune entries older than their windows
  for (const [key, ts] of slashCooldownByUser) {
    if (now - ts > 60 * 1000) slashCooldownByUser.delete(key);
  }
}, 10 * 60 * 1000); // every 10 minutes

/* ── Restock notifications: DM/email members who asked to be notified ── */
async function notifyRestockWaiters(filterSlug = null) {
  if (!supabaseAdmin) return;
  try {
    let q = supabaseAdmin
      .from("restock_notifications")
      .select("id, product_slug, product_name, email, discord_id")
      .is("notified_at", null);
    if (filterSlug) q = q.eq("product_slug", filterSlug);
    const { data: pending } = await q.limit(500);
    if (!pending || !pending.length) return;

    const nowIso = new Date().toISOString();
    for (const n of pending) {
      const label = n.product_name || n.product_slug;
      if (discordBot && n.discord_id) {
        try {
          const u = await discordBot.users.fetch(n.discord_id);
          await u.send({
            embeds: [{
              title: "Back in Stock",
              description: `**${label}** is available again.`,
              color: 0x00c851,
              fields: [{ name: "Get it", value: `[View Products](${baseUrl}/products/)`, inline: false }],
              footer: { text: "XenCheats" },
            }],
          });
        } catch {}
      }
      if (resendApiKey && n.email) {
        try {
          const { default: fetch } = await import("node-fetch");
          await fetch("https://api.resend.com/emails", {
            method: "POST",
            headers: { Authorization: `Bearer ${resendApiKey}`, "Content-Type": "application/json" },
            body: JSON.stringify({
              from: "XenCheats <noreply@xencheats.wtf>",
              to: [n.email],
              subject: `${label} is back in stock`,
              html: `<p><strong>${label}</strong> is available again at <a href="${baseUrl}/products/">xencheats.wtf</a>.</p>`,
            }),
          });
        } catch {}
      }
      await supabaseAdmin.from("restock_notifications").update({ notified_at: nowIso }).eq("id", n.id);
    }
    console.log(`[Restock notify] Notified ${pending.length} waiter(s)${filterSlug ? ` for ${filterSlug}` : ""}`);
  } catch (err) {
    console.error("[Restock notify]", err.message);
  }
}

/* ── Restock alerts ── */
const lastStockCounts = new Map();
let restockInitialized = false;

async function checkRestockAlerts() {
  if (!supabaseAdmin || !discordBot || !discordRestockChannelId) return;

  try {
    const counts = await getUnusedLicenseKeyCounts();

    if (!restockInitialized) {
      // First run: just save current counts, don't alert
      for (const [slug, count] of counts) {
        lastStockCounts.set(slug, count);
      }
      restockInitialized = true;
      console.log("[Restock] Initialized stock snapshot");
      return;
    }

    for (const [slug, count] of counts) {
      const prev = lastStockCounts.get(slug) || 0;

      if (count > prev && prev === 0) {
        // Product went from 0 to in-stock: restock alert
        const catalogItem = getCatalogItemByInventorySlug(slug);
        const productLabel = catalogItem?.name || slug;

        try {
          const channel = await discordBot.channels.fetch(discordRestockChannelId);
          if (channel) {
            await channel.send({
              embeds: [{
                title: "Restock Alert",
                description: `**${productLabel}** is back in stock! (${count} ${count === 1 ? "key" : "keys"} available)`,
                color: 0x00c851,
                timestamp: new Date().toISOString(),
                footer: { text: "XenCheats" },
              }],
            });
          }
        } catch (sendErr) {
          console.error("[Restock] Channel send error:", sendErr.message);
        }

        /* Notify members waiting on this product (map inventory slug -> catalog slug) */
        if (catalogItem?.slug) notifyRestockWaiters(catalogItem.slug);
      }

      lastStockCounts.set(slug, count);
    }

    // Also check for products that went to 0 (removed from counts map)
    for (const [slug] of lastStockCounts) {
      if (!counts.has(slug)) {
        lastStockCounts.set(slug, 0);
      }
    }
  } catch (err) {
    console.error("[Restock check]", err.message);
  }
}

// Run every 2 minutes
setInterval(checkRestockAlerts, 2 * 60 * 1000);
setTimeout(checkRestockAlerts, 10_000); // first check 10s after boot

/* ── Automatic retry queue for orders that paid but couldn't be fulfilled ──
   Populated by handleOrderIdSubmission (above) when a signed-in customer
   pastes a genuinely unfulfilled Order ID into live desk chat. Runs on a
   cheap 30-minute cadence and only touches rows that are actually due —
   this project has been bitten before by over-eager background polling
   (see the Cheats.Love ban), so this deliberately stays well above any
   per-minute cadence. */
async function processDueOrderRetryJobs() {
  if (!supabaseAdmin) return;
  try {
    const { data: dueJobs, error } = await supabaseAdmin
      .from("order_retry_jobs")
      .select("id, order_id, thread_id, discord_channel_id, attempts, max_attempts")
      .eq("status", "active")
      .lte("next_attempt_at", new Date().toISOString());

    if (error) {
      console.error("[Order retry jobs] Query error:", error.message);
      return;
    }

    if (!dueJobs || !dueJobs.length) return;

    for (const job of dueJobs) {
      try {
        await processOneOrderRetryJob(job);
      } catch (jobError) {
        console.error(`[Order retry jobs] Job ${job.id} error:`, jobError.message);
      }
    }
  } catch (err) {
    console.error("[Order retry jobs] Processor error:", err.message);
  }
}

async function processOneOrderRetryJob(job) {
  const { data: order, error: orderError } = await supabaseAdmin
    .from("orders")
    .select("id, status, product_slug, stripe_session_id, stripe_payment_intent, delivered_key_value")
    .eq("id", job.order_id)
    .maybeSingle();

  if (orderError || !order) {
    console.error(`[Order retry jobs] Order lookup failed for job ${job.id}:`, orderError?.message || "not found");
    return;
  }

  let thread = null;
  if (job.thread_id) {
    const { data } = await supabaseAdmin
      .from("support_threads")
      .select("id, discord_thread_id")
      .eq("id", job.thread_id)
      .maybeSingle();
    thread = data || null;
  }

  /* Discord-ticket-linked jobs (no thread_id) post straight into the ticket
     channel instead of a mirrored support thread. Resolve it once up front
     — if the channel is gone (ticket closed/archived, channel deleted), give
     up on this job now rather than retrying forever against a channel that
     no longer exists. If the bot just isn't connected at this exact tick,
     leave the job active so the next 30-minute sweep can try again. */
  let discordTicketChannel = null;
  if (!thread && job.discord_channel_id) {
    if (!discordBot) return;
    try {
      discordTicketChannel = await discordBot.channels.fetch(job.discord_channel_id);
    } catch (fetchError) {
      console.error(`[Order retry jobs] Discord ticket channel unavailable for job ${job.id}:`, fetchError.message);
    }
    if (!discordTicketChannel) {
      await supabaseAdmin
        .from("order_retry_jobs")
        .update({
          status: "cancelled",
          last_error: "Discord ticket channel no longer exists",
          updated_at: new Date().toISOString(),
        })
        .eq("id", job.id);
      return;
    }
  }

  const postUpdate = async (body, prefix = "AI") => {
    if (thread) {
      const insertResult = await supabaseAdmin.from("support_messages").insert({
        thread_id: thread.id,
        sender_type: "bot",
        body,
      });
      if (insertResult.error) {
        console.error(`[Order retry jobs] Message insert error for job ${job.id}:`, insertResult.error.message);
      }
      await supabaseAdmin
        .from("support_threads")
        .update({ updated_at: new Date().toISOString(), last_message_at: new Date().toISOString() })
        .eq("id", thread.id);
      await mirrorToSupportThread(thread.id, thread.discord_thread_id, prefix, body);
      return;
    }

    if (discordTicketChannel) {
      try {
        await discordTicketChannel.send(body);
      } catch (sendError) {
        console.error(`[Order retry jobs] Discord channel send failed for job ${job.id}:`, sendError.message);
      }
    }
  };

  /* Already fulfilled through some other path (e.g. /retryunfulfilled, the
     account page's own auto-heal) — close the job out instead of retrying. */
  if (order.status === "fulfilled") {
    await supabaseAdmin
      .from("order_retry_jobs")
      .update({ status: "completed", updated_at: new Date().toISOString() })
      .eq("id", job.id);
    await postUpdate(`Good news — your key just came through: \`${order.delivered_key_value || ""}\`. Enjoy!`);
    return;
  }

  let syncResult;
  let syncErrorMessage = null;
  try {
    syncResult = await syncPaidOrder({
      id: order.stripe_session_id,
      payment_intent: order.stripe_payment_intent,
      metadata: { orderId: order.id },
    });
  } catch (syncError) {
    syncErrorMessage = syncError.message;
    syncResult = undefined;
  }

  if (syncResult?.keyValue) {
    await supabaseAdmin
      .from("order_retry_jobs")
      .update({ status: "completed", updated_at: new Date().toISOString() })
      .eq("id", job.id);
    await postUpdate(`Good news — your key just came through: \`${syncResult.keyValue}\`. Enjoy!`);
    return;
  }

  /* syncPaidOrder returns undefined both when the order is still unfulfilled
     AND when it was fulfilled through some other path during this call —
     re-query to tell those apart before counting this as a failed attempt. */
  const { data: freshOrder } = await supabaseAdmin
    .from("orders")
    .select("status, delivered_key_value")
    .eq("id", order.id)
    .maybeSingle();

  if (freshOrder?.status === "fulfilled") {
    await supabaseAdmin
      .from("order_retry_jobs")
      .update({ status: "completed", updated_at: new Date().toISOString() })
      .eq("id", job.id);
    await postUpdate(`Good news — your key just came through: \`${freshOrder.delivered_key_value || ""}\`. Enjoy!`);
    return;
  }

  const attempts = (job.attempts || 0) + 1;
  const maxAttempts = job.max_attempts || 12;

  if (attempts >= maxAttempts) {
    await supabaseAdmin
      .from("order_retry_jobs")
      .update({
        status: "failed",
        attempts,
        last_error: syncErrorMessage,
        updated_at: new Date().toISOString(),
      })
      .eq("id", job.id);

    await postUpdate("This is taking longer than expected — I've flagged it for our team to look at manually, sorry for the wait.");

    /* Extra staff-alert line so this doesn't sit silently unnoticed — same
       idea as the @-mention handleUnfulfilledOrder sends to the low-stock
       channel, just aimed at wherever this ticket lives. */
    if (thread) {
      const staffMention = BOT_ADMINS.map((id) => `<@${id}>`).join(" ");
      await mirrorToSupportThread(
        thread.id,
        thread.discord_thread_id,
        "System",
        `${staffMention} Order ${order.id} has failed automatic retry ${maxAttempts} times and needs manual attention.`
      );
    } else if (discordTicketChannel) {
      const staffMentionRoleId = discordEmployeeRoleId || discordAdminRoleId || discordOwnerRoleId;
      if (staffMentionRoleId) {
        try {
          await discordTicketChannel.send({
            content: `<@&${staffMentionRoleId}> Order ${order.id} has failed automatic retry ${maxAttempts} times and needs manual attention.`,
            allowedMentions: { roles: [staffMentionRoleId] },
          });
        } catch (mentionError) {
          console.error(`[Order retry jobs] Discord staff ping failed for job ${job.id}:`, mentionError.message);
        }
      }
    }
    return;
  }

  const nextAttemptAt = new Date(Date.now() + 6 * 60 * 60 * 1000).toISOString();
  await supabaseAdmin
    .from("order_retry_jobs")
    .update({
      attempts,
      next_attempt_at: nextAttemptAt,
      last_error: syncErrorMessage,
      updated_at: new Date().toISOString(),
    })
    .eq("id", job.id);

  await postUpdate("Retried again — still not there, next attempt in about 6 hours.");
}

setInterval(() => {
  processDueOrderRetryJobs().catch((err) => console.error("[Order retry jobs] Interval error:", err.message));
}, 30 * 60 * 1000).unref();
setTimeout(() => {
  processDueOrderRetryJobs().catch((err) => console.error("[Order retry jobs] Boot warm-up error:", err.message));
}, 20_000).unref(); // first sweep 20s after boot

/* ── 404 catch-all ── */
app.use((_req, res) => {
  res.status(404).sendFile(path.join(distDir, "404.html"));
});

/* ── Load product overrides from Supabase on startup ── */
async function loadProductOverrides() {
  if (!supabaseAdmin) return;
  try {
    const { data, error } = await supabaseAdmin
      .from("product_overrides")
      .select("product_slug, variant_slug, available, amount");
    if (error) { console.error("Failed to load product overrides:", error.message); return; }
    if (!data || !data.length) return;

    for (const row of data) {
      const product = products.find((p) => p.slug === row.product_slug);
      if (!product) continue;

      if (row.variant_slug === null && typeof row.available === "boolean") {
        product.available = row.available;
      }

      if (row.variant_slug) {
        const variant = product.variants?.find((v) => v.slug === row.variant_slug);
        if (variant && typeof row.amount === "number") {
          variant.amount = row.amount;
          variant.priceDisplay = `$${(row.amount / 100).toFixed(2)}`;
        }
      }
    }
    // Recalculate "From $X.XX" for any product that had variant overrides
    const touched = new Set(data.filter((r) => r.variant_slug).map((r) => r.product_slug));
    for (const slug of touched) {
      const product = products.find((p) => p.slug === slug);
      if (product?.variants?.length) {
        const minAmount = Math.min(...product.variants.map((v) => v.amount));
        product.priceDisplay = `From $${(minAmount / 100).toFixed(2)}`;
      }
    }
    console.log(`Loaded ${data.length} product override(s) from database.`);
  } catch (err) {
    console.error("Error loading product overrides:", err.message);
  }
}

/* Live "Undetected/Updating/etc" badges written by the Discord status-sync bot
   (see the Product status sync block above). Reads from Supabase instead of
   requiring a redeploy every time a badge changes. Runs once at startup and
   then on a timer so the site picks up bot-driven changes without a restart. */
async function loadProductStatusOverrides() {
  if (!supabaseAdmin) return;
  try {
    const { data, error } = await supabaseAdmin
      .from("product_status_overrides")
      .select("product_slug, badge");
    if (error) {
      console.error("[Status sync] Failed to load status overrides:", error.message);
      return;
    }
    if (!data || !data.length) return;
    for (const row of data) {
      const product = products.find((p) => p.slug === row.product_slug);
      if (product && row.badge) applyProductStatusBadge(product, row.badge);
    }
    console.log(`[Status sync] Loaded ${data.length} product status override(s) from database.`);
  } catch (err) {
    console.error("[Status sync] Error loading status overrides:", err.message);
  }
}

/* ── Cheats.Love reseller stock sync ──
   Polls GET /products on the Cheats.Love reseller API on a timer and keeps
   our in-memory `stockLabel` per variant AND `cheatsloveStockKnown` (top of
   file) in sync with their live stock, so the site never shows a variant as
   "In Stock" when the upstream reseller panel is actually out.

   The API key is read from process.env.CHEATSLOVE_API_KEY only (set it on
   Render — never hardcode it here, this repo is public).

   Matching: Cheats.Love product/variation names won't necessarily match our
   catalog's names or slugs exactly, and guessing wrong marks a real
   in-stock product as "Out of Stock" site-wide — worse than not syncing at
   all. So a variant's stock is only ever changed when we're confident:
     1. It's explicitly pinned in CHEATSLOVE_VID_MAP below
        (`${productSlug}-${variantSlug}` -> the Cheats.Love variation id), or
     2. It auto-matches — the product's `name` equals a Cheats.Love product
        name exactly (case/punctuation-insensitive) AND the variant's
        duration (1 Day / 7 Day / 30 Day / 90 Day, etc.) equals a variation's
        duration exactly. No fuzzy/partial matching.
   Manual pins always win over an auto-match for the same inventorySlug.
   Everything else is left alone and logged as unmatched on the first cycle
   so you can look up the real vids from that log and add them here. */
  let cheatsloveCatalogLogged = false;
  let cheatsloveUnmatchedLogged = false;
  let cheatsloveAutoMatchLogged = false;
  let cheatsloveSyncRunning = false;
  let cheatsloveSyncWaiters = [];
  let cheatsloveStoreSyncRunning = false;

  function parseCheatsloveRetryAfter(value) {
    if (!value) return CHEATSLOVE_MIN_429_COOLDOWN_MS;
    const seconds = Number(value);
    if (Number.isFinite(seconds)) {
      return Math.max(CHEATSLOVE_MIN_429_COOLDOWN_MS, Math.ceil(seconds * 1_000));
    }
    const retryAt = Date.parse(value);
    return Number.isFinite(retryAt)
      ? Math.max(CHEATSLOVE_MIN_429_COOLDOWN_MS, retryAt - Date.now())
      : CHEATSLOVE_MIN_429_COOLDOWN_MS;
  }

  async function cheatsloveFetch(path, options = {}) {
    const request = cheatsloveRequestQueue.then(async () => {
      const earliestStart = Math.max(
        cheatsloveBlockedUntil,
        cheatsloveLastRequestStartedAt + CHEATSLOVE_MIN_REQUEST_INTERVAL_MS,
      );
      const waitMs = earliestStart - Date.now();
      if (waitMs > 0) {
        await new Promise((resolve) => setTimeout(resolve, waitMs));
      }

      cheatsloveLastRequestStartedAt = Date.now();
      const res = await fetch(`${cheatsloveBaseUrl}${path}`, {
        method: options.method || "GET",
        headers: {
          Authorization: `Bearer ${cheatsloveApiKey}`,
          Accept: "application/json",
          "User-Agent": "Mozilla/5.0 (compatible; XenCheats-StockMonitor/1.0; +https://xencheats.wtf)",
          ...(options.body ? { "Content-Type": "application/json" } : {}),
        },
        body: options.body,
        signal: AbortSignal.timeout(CHEATSLOVE_REQUEST_TIMEOUT_MS),
      });
      if (res.status === 429) {
        const cooldownMs = parseCheatsloveRetryAfter(res.headers.get("retry-after"));
        cheatsloveBlockedUntil = Math.max(cheatsloveBlockedUntil, Date.now() + cooldownMs);
        throw new Error(`Cheats.Love rate limit hit (429) - queue paused for ${Math.ceil(cooldownMs / 1_000)}s`);
      }
      if (!res.ok) {
        throw new Error(`Cheats.Love API ${path} failed: ${res.status}`);
      }
      return res.json();
    });

    /* Keep later calls moving even if this request fails. Returning `request`
       still preserves the original rejection for its caller. */
    cheatsloveRequestQueue = request.catch(() => undefined);
    return request;
  }

  function resolveCheatsloveStock(variation) {
    // stock: null with a human stock_display (e.g. "< 10") means tracked but
    // not exact; a numeric stock is an exact count; treat 0 as out of stock.
    if (typeof variation.stock === "number") {
      return variation.stock > 0 ? "In Stock" : "Out of Stock";
    }
    if (typeof variation.stock_display === "string" && variation.stock_display.trim()) {
      const text = variation.stock_display.trim();
      if (/^0$|out of stock|unavailable/i.test(text)) return "Out of Stock";
      return "In Stock";
    }
    return null;
  }

  /* Lowercase + strip all non-alphanumerics so "EFT – Chams+" and "EFT - Chams+"
     (curly vs plain dash, trailing +) compare equal. Exact match only. */
  function cheatsloveNormalizeName(s) {
    return String(s || "").toLowerCase().replace(/[^a-z0-9]+/g, "");
  }

  /* Maps a human duration string ("1 Day", "7 Day Key", "3 Month", "90 Day Key")
     to a canonical bucket so both sides of the match use the same units. */
  function cheatsloveDurationKey(label) {
    const m = String(label || "").toLowerCase().match(/(\d+)\s*(day|week|month)/);
    if (!m) return null;
    const n = Number(m[1]);
    const unit = m[2];
    if (unit === "day") {
      if (n === 1) return "day";
      if (n === 7) return "week";
      if (n === 30) return "month";
      if (n === 90) return "three-month";
    }
    if (unit === "week" && n === 1) return "week";
    if (unit === "month") {
      if (n === 1) return "month";
      if (n === 3) return "three-month";
    }
    return `${n}${unit}`;
  }

  /* Posts one batched embed for every variant that flipped from out-of-stock
     (or a known 0 count) to available during this sync pass. Batched instead
     of one message per variant since a single supplier catalog refresh can
     restock several variants at once. */
  async function postRestockAnnouncement(restocked) {
    if (!discordBot || !discordRestockChannelId || !restocked.length) return;
    try {
      const channel = await discordBot.channels.fetch(discordRestockChannelId).catch(() => null);
      if (!channel?.isTextBased?.()) return;
      const shown = restocked.slice(0, 40);
      const lines = shown.map((r) => {
        const countText = Number.isInteger(r.stockCount) ? ` — **${r.stockCount}** available` : "";
        return `• **${r.productName} — ${r.variantName}**${countText}`;
      });
      const extra = restocked.length > shown.length ? `\n...and ${restocked.length - shown.length} more.` : "";
      await channel.send({
        embeds: [{
          title: "📦 Back in stock",
          description: `${lines.join("\n")}${extra}`,
          color: 0x22c55e,
          footer: { text: "XenCheats | Stock sync" },
          timestamp: new Date().toISOString(),
        }],
      });
    } catch (err) {
      console.error("[Restock announce]", err.message);
    }
  }

  async function syncCheatsLoveStock({ refreshBalance = true } = {}) {
    if (!cheatsloveApiKey) return;
    if (cheatsloveSyncRunning) {
      return new Promise((resolve) => cheatsloveSyncWaiters.push(resolve));
    }
    cheatsloveSyncRunning = true;
    try {
      const data = await cheatsloveFetch("/products");
      const clProducts = Array.isArray(data?.products) ? data.products : [];
      if (!clProducts.length) {
        cheatsloveLastStockSyncFailed = true;
        return;
      }
      cheatsloveLastStockSyncFailed = false;

      if (refreshBalance) {
        try {
          const balanceData = await cheatsloveFetch("/balance");
          const balance = Number(balanceData?.balance);
          if (Number.isFinite(balance)) cheatsloveBalanceCents = Math.round(balance * 100);
        } catch (balanceError) {
          console.warn(`[Cheats.Love] Balance check failed: ${balanceError.message}`);
        }
      }

      const byVid = new Map();
      const clByName = new Map();
      const clProductIds = new Set();
      for (const clProduct of clProducts) {
        const clProductId = Number(clProduct.id);
        if (Number.isInteger(clProductId)) clProductIds.add(clProductId);
        clByName.set(cheatsloveNormalizeName(clProduct.name), clProduct);
        for (const variation of clProduct.variations || []) {
          byVid.set(String(variation.id), {
            productName: clProduct.name,
            label: variation.label,
            stock: resolveCheatsloveStock(variation),
            stockCount: variation.stock !== null && variation.stock !== "" && Number.isFinite(Number(variation.stock))
              ? Math.max(0, Math.trunc(Number(variation.stock)))
              : null,
            costCents: Number.isFinite(Number(variation.reseller))
              ? Math.round(Number(variation.reseller) * 100)
              : null,
          });
        }
      }
      for (const product of products) {
        const productId = Number(product.cheatsLoveProductId);
        cheatsloveProductPresenceKnown.set(
          product.slug,
          Number.isInteger(productId) && clProductIds.has(productId)
        );
      }
      cheatsloveProductPresenceReady = true;

      if (!cheatsloveCatalogLogged) {
        cheatsloveCatalogLogged = true;
        const sample = clProducts
          .slice(0, 20)
          .map((p) => `${p.name} [${(p.variations || []).map((v) => `${v.label}=${v.id}`).join(", ")}]`)
          .join(" | ");
        console.log(
          `[Cheats.Love] Catalog loaded: ${clProducts.length} product(s). ` +
          `Stock is applied to manually pinned CHEATSLOVE_VID_MAP entries plus safe exact-name auto-matches. ` +
          `Full dump for manual pinning of anything still unmatched: ${sample}`
        );
      }

      // Safe exact-match auto-pin: product name + variant duration must both
      // match exactly. Manual CHEATSLOVE_VID_MAP entries always take priority.
      const autoMatchedVids = new Map(); // inventorySlug -> vid
      const autoMatchLog = [];
      for (const product of products) {
        const clProduct = clByName.get(cheatsloveNormalizeName(product.name));
        if (!clProduct) continue;
        for (const variant of product.variants || []) {
          const inventorySlug = variant.inventorySlug || `${product.slug}-${variant.slug}`;
          if (inventorySlug in CHEATSLOVE_VID_MAP) continue; // manual pin wins
          const wantKey = cheatsloveDurationKey(variant.name);
          if (!wantKey) continue;
          const match = (clProduct.variations || []).find(
            (v) => cheatsloveDurationKey(v.label) === wantKey
          );
          if (match) {
            autoMatchedVids.set(inventorySlug, String(match.id));
            autoMatchLog.push(`${inventorySlug}->${match.id}`);
          }
        }
      }
      if (autoMatchedVids.size && !cheatsloveAutoMatchLogged) {
        cheatsloveAutoMatchLogged = true;
        console.log(`[Cheats.Love] Auto-matched ${autoMatchedVids.size} variant(s) by exact name+duration: ${autoMatchLog.join(", ")}`);
      }

      const resolvedVidBySlug = new Map([...autoMatchedVids, ...Object.entries(CHEATSLOVE_VID_MAP)]);
      if (!resolvedVidBySlug.size) return; // nothing pinned or matched — don't touch stock labels

      let updatedCount = 0;
      const unmatched = [];
      const cacheRows = [];
      // Variants that flip from out-of-stock/0 to available during this
      // pass — collected here, announced once as a batch after the loop.
      const restocked = [];

      for (const product of products) {
        const productId = Number(product.cheatsLoveProductId);
        for (const variant of product.variants || []) {
          const inventorySlug = variant.inventorySlug || `${product.slug}-${variant.slug}`;
          if (!resolvedVidBySlug.has(inventorySlug)) continue; // not pinned/matched — leave as-is

          // Snapshot the state BEFORE this pass overwrites it. Only fire a
          // restock alert when we actually had a prior known state (so a
          // brand-new product/variant showing up for the first time isn't
          // announced as a "restock") and that state was out-of-stock/0.
          const hadPriorState = cheatsloveStockKnown.has(inventorySlug);
          const wasOutOfStock = hadPriorState
            && (cheatsloveStockKnown.get(inventorySlug) !== "In Stock" || cheatsloveStockCountKnown.get(inventorySlug) === 0);

          const stockInfo = byVid.get(String(resolvedVidBySlug.get(inventorySlug))) || null;
          if (!stockInfo || stockInfo.stock == null) {
            unmatched.push(inventorySlug);
            cheatsloveStockKnown.set(inventorySlug, "Out of Stock");
            cheatsloveStockCountKnown.set(inventorySlug, 0);
            cacheRows.push({
              inventory_slug: inventorySlug,
              product_slug: product.slug,
              upstream_product_id: Number.isInteger(productId) ? productId : null,
              stock_label: "Out of Stock",
              stock_count: 0,
              cost_cents: null,
            });
            continue;
          }

          const willBeInStock = stockInfo.stock === "In Stock" && (!Number.isInteger(stockInfo.stockCount) || stockInfo.stockCount > 0);
          if (hadPriorState && wasOutOfStock && willBeInStock) {
            restocked.push({
              productName: product.name,
              variantName: variant.name,
              stockCount: Number.isInteger(stockInfo.stockCount) ? stockInfo.stockCount : null,
            });
          }

          cheatsloveStockKnown.set(inventorySlug, stockInfo.stock);
          if (Number.isInteger(stockInfo.stockCount)) {
            cheatsloveStockCountKnown.set(inventorySlug, stockInfo.stockCount);
          } else {
            cheatsloveStockCountKnown.delete(inventorySlug);
          }
          if (Number.isFinite(stockInfo.costCents)) {
            cheatsloveCostKnown.set(inventorySlug, stockInfo.costCents);
          }
          cacheRows.push({
            inventory_slug: inventorySlug,
            product_slug: product.slug,
            upstream_product_id: Number.isInteger(productId) ? productId : null,
            stock_label: stockInfo.stock,
            stock_count: Number.isInteger(stockInfo.stockCount) ? stockInfo.stockCount : null,
            cost_cents: Number.isFinite(stockInfo.costCents) ? stockInfo.costCents : null,
            synced_at: new Date().toISOString(),
          });
          if (variant.stockLabel !== stockInfo.stock) {
            variant.stockLabel = stockInfo.stock;
            updatedCount += 1;
          }
        }
      }

      cheatsloveLastStockSyncAt = Date.now();

      if (supabaseAdmin && cacheRows.length) {
        const syncedAt = new Date().toISOString();
        await supabaseAdmin.from("supplier_stock_cache").upsert(
          cacheRows.map((row) => ({ ...row, synced_at: syncedAt })),
          { onConflict: "inventory_slug" },
        );
        await supabaseAdmin.from("supplier_stock_sync_state").upsert({
          id: "catalog",
          upstream_product_ids: [...clProductIds],
          synced_at: syncedAt,
        }, { onConflict: "id" });
      }

      if (updatedCount) {
        console.log(`[Cheats.Love] Updated stock for ${updatedCount} variant(s).`);
      }
      if (restocked.length) {
        postRestockAnnouncement(restocked).catch((err) => console.error("[Restock announce]", err.message));
      }
      if (unmatched.length && !cheatsloveUnmatchedLogged) {
        cheatsloveUnmatchedLogged = true;
        console.log(`[Cheats.Love] Pinned/matched vid returned no stock data for: ${unmatched.join(", ")}`);
      }
    } catch (err) {
      cheatsloveLastStockSyncFailed = true;
      console.error("[Cheats.Love] Stock sync error:", err.message);
    } finally {
      cheatsloveSyncRunning = false;
      const waiters = cheatsloveSyncWaiters;
      cheatsloveSyncWaiters = [];
      for (const resolve of waiters) resolve();
    }
  }

  async function syncCheatsLoveStoreStock() {
    if (!cheatsloveApiKey || cheatsloveStoreSyncRunning) return;
    cheatsloveStoreSyncRunning = true;

    const variants = products.flatMap((product) =>
      (product.variants || [])
        .filter((variant) => Number.isInteger(variant.cheatsLoveVariationId))
        .map((variant) => ({
          inventorySlug: variant.inventorySlug || `${product.slug}-${variant.slug}`,
          variationId: variant.cheatsLoveVariationId,
          label: `${product.name} - ${variant.name}`,
        }))
    );
    const results = new Array(variants.length);
    let cursor = 0;

    async function worker() {
      while (cursor < variants.length) {
        const index = cursor++;
        const variant = variants[index];
        try {
          const response = await fetch(`${cheatsloveStoreApiUrl}/products/${variant.variationId}`, {
            headers: { Accept: "application/json" },
            signal: AbortSignal.timeout(10_000),
          });
          if (!response.ok) throw new Error(`HTTP ${response.status}`);
          const data = await response.json();
          results[index] = {
            ...variant,
            stock: data?.is_in_stock === true ? "In Stock" : "Out of Stock",
          };
        } catch (error) {
          console.warn(`[Cheats.Love Store] ${variant.variationId} check failed: ${error.message}`);
        }
      }
    }

    try {
      const catalogResponse = await fetch(`${cheatsloveStoreApiUrl}/products?per_page=100&page=1`, {
        headers: { Accept: "application/json" },
        signal: AbortSignal.timeout(15_000),
      });
      if (!catalogResponse.ok) throw new Error(`catalog HTTP ${catalogResponse.status}`);
      const storefrontProducts = await catalogResponse.json();
      if (!Array.isArray(storefrontProducts) || !storefrontProducts.length) {
        throw new Error("storefront catalog returned no products");
      }
      const storefrontProductIds = new Set(
        storefrontProducts.map((product) => Number(product.id)).filter(Number.isInteger)
      );
      for (const product of products) {
        const productId = Number(product.cheatsLoveProductId);
        cheatsloveProductPresenceKnown.set(
          product.slug,
          Number.isInteger(productId) && storefrontProductIds.has(productId)
        );
      }
      cheatsloveProductPresenceReady = true;

      await Promise.all(Array.from({ length: 8 }, () => worker()));
      const valid = results.filter(Boolean);
      if (valid.length < Math.ceil(variants.length * 0.8)) {
        throw new Error(`only ${valid.length}/${variants.length} stock checks succeeded`);
      }

      const newlyOut = [];
      for (const result of valid) {
        const previous = cheatsloveStoreStockKnown.get(result.inventorySlug);
        cheatsloveStoreStockKnown.set(result.inventorySlug, result.stock);
        if (result.stock === "Out of Stock" && previous === "In Stock") newlyOut.push(result.label);
      }
      cheatsloveStoreStockSyncReady = true;
      cheatsloveLastStoreStockSyncAt = Date.now();
      const outCount = valid.filter((result) => result.stock === "Out of Stock").length;
      console.log(`[Cheats.Love Store] Confirmed ${valid.length} variant(s); ${outCount} out of stock.`);

      if (newlyOut.length && discordBot && discordLowStockChannelId) {
        try {
          const channel = await discordBot.channels.fetch(discordLowStockChannelId);
          await channel?.send({
            embeds: [{
              title: "Supplier stock changed",
              description: newlyOut.map((label) => `- ${label}`).join("\n").slice(0, 3900),
              color: 0xed4245,
              footer: { text: "These variants are now disabled on XenCheats." },
              timestamp: new Date().toISOString(),
            }],
          });
        } catch (error) {
          console.error("[Cheats.Love Store alert]", error.message);
        }
      }
    } catch (error) {
      console.error("[Cheats.Love Store] Stock sync error:", error.message);
    } finally {
      cheatsloveStoreSyncRunning = false;
    }
  }

Promise.all([loadProductOverrides(), loadProductStatusOverrides(), loadSupplierStockCache()]).then(async () => {
  setInterval(loadProductStatusOverrides, 5 * 60 * 1000).unref();

  /* Stock alone is not enough to decide whether checkout can fulfill an
     order: reseller coverage also depends on the current supplier balance.
     Refresh both together so a balance top-up takes effect without waiting
     for a server restart. The shared provider queue and cart cooldown still
     keep these calls well below the API rate limit. */
  requestCheatsLoveStockRefresh = () => syncCheatsLoveStock({ refreshBalance: true });

  /* One authenticated /products request returns every variant quantity, and
     one /balance request confirms the reseller account can cover fulfillment.
     Refresh both hourly, with a cooldown-limited refresh when a customer adds
     an item to their cart. All supplier calls still pass
     through cheatsloveFetch(), whose hard four-second spacing caps the whole
     app at 15 requests/minute, below the documented 30/minute provider limit.
     The retired per-variant storefront checker remains unused. */
  if (cheatsloveApiKey) {
    /* Warm the in-memory snapshot before accepting traffic. This keeps the
       first catalog request fast and prevents a stale/empty cache from being
       presented as the current supplier stock. */
    try {
      await syncCheatsLoveStock();
    } catch (error) {
      console.error("[Cheats.Love] Initial stock sync failed:", error.message);
    }
    console.log(
      `[Cheats.Love] Stock snapshot ready: ${cheatsloveLastStockSyncFailed ? "FAILED (fail-closed)" : "OK"}; ` +
      `mapped=${Object.keys(CHEATSLOVE_VID_MAP).length}; endpoint=${cheatsloveBaseUrl}`
    );
    setInterval(() => void syncCheatsLoveStock({ refreshBalance: true }), cheatslovePollMs).unref();
    console.log("[Cheats.Love] Catalog stock and reseller balance monitor enabled with cooldown-limited cart refreshes.");
  } else {
    console.log("[Cheats.Love] CHEATSLOVE_API_KEY not set — stock sync disabled.");
  }

  if (sellAuthResellerApiKey) {
    await syncSellAuthCatalog({ force: true });
    setInterval(() => void syncSellAuthCatalog({ force: true }), sellAuthCatalogTtlMs).unref();
    console.log(`[SellAuth] Catalog monitor enabled: one request every ${Math.round(sellAuthCatalogTtlMs / 60_000)} minute(s).`);
  } else {
    console.log("[SellAuth] SELLAUTH_RESELLER_API_KEY not set - supplier digital checkout is fail-closed.");
  }

  const httpServer = app.listen(port, () => {
    console.log(`API server listening on http://localhost:${port}`);
  });

  /* Graceful shutdown: Render sends SIGTERM on every deploy. Close the Discord
     gateway and stop accepting HTTP connections instead of dying mid-request. */
  let shuttingDown = false;
  const shutdown = (signal) => {
    if (shuttingDown) return;
    shuttingDown = true;
    console.log(`[shutdown] ${signal} received — closing HTTP server and Discord client...`);
    try {
      if (discordBot) discordBot.destroy();
    } catch (err) {
      console.error("[shutdown] Discord destroy failed:", err?.message || err);
    }
    httpServer.close(() => process.exit(0));
    /* Force-exit if lingering connections keep the server open */
    setTimeout(() => process.exit(0), 8_000).unref();
  };
  process.on("SIGTERM", () => shutdown("SIGTERM"));
  process.on("SIGINT", () => shutdown("SIGINT"));
});
